def bread(pairs):
    links=['<a href="/">HOME</a>']+[f'<a href="{u}">{h(t).upper()}</a>' for t,u in pairs[:-1]]
    return '<div class="crumb">'+'<span> / </span>'.join(links+[h(pairs[-1][0]).upper()])+'</div>'

