def facts_page():
    """A source-first, entity-focused reference page for web and AI retrieval."""
    path='/gta-6-facts/'
    desc='A current, source-checked breakdown of what Rockstar has confirmed about GTA VI, plus unknown details that should not be presented as facts.'
    facts=[
        ('Release date','Thursday, November 19, 2026. Digital unlock timing varies by storefront region.','/guides/gta-6-release-date-and-time/'),
        ('Launch platforms','PlayStation 5 and Xbox Series X|S. No official PC release date or PC minimum specifications are announced.','/guides/gta-6-pc-release-system-requirements/'),
        ('Setting','The fictional state of Leonida includes Vice City, Leonida Keys, Grassrivers, Port Gellhorn, Ambrosia and Mount Kalaga.','/map/'),
        ('Playable leads','Rockstar introduces Jason Duval and Lucia Caminos as the central protagonists.','/characters/'),
        ('PS5 storage','PlayStation advises at least 212 GB of free space before installing GTA VI. Download sizes and Xbox storage are not necessarily identical.','/guides/gta-6-download-size-ps5-xbox/'),
        ('Editions','Rockstar offers Standard and Ultimate editions; confirm what extras are included in your country.','/guides/gta-6-editions-compared/'),
        ('Physical retail','Listings described as Code-in-Box contain a redeemable download code rather than a game disc.','/buy/'),
        ('Preload','Rockstar announced preloading for eligible digital orders beginning November 10, 2026.','/guides/how-to-preload-gta-6/')
    ]
    questions=[
      ('When is GTA 6 released?','Rockstar lists November 19, 2026 for the PS5 and Xbox Series X|S release.'),
      ('Will GTA 6 launch on PC?','A PC date and official PC specifications have not been announced in Rockstar’s published launch information.'),
      ('Who are the two central GTA 6 characters?','Jason Duval and Lucia Caminos.'),
      ('Is the full GTA 6 map confirmed?','No. Rockstar names multiple Leonida regions, but pre-release building-level maps are community reconstructions.'),
      ('What storage space is needed on PS5?','PlayStation recommends freeing at least 212 GB on PS5. Actual file download size is not the same as the advised space target.')
    ]
    fact_html=''.join(f'<div class="fact-block"><span class="section-label">// {h(label.upper())}</span><p>{h(value)}</p><a href="{url}">SEE DETAILS &#8594;</a></div>' for label,value,url in facts)
    q_html=''.join(f'<details class="faq"><summary>{h(q)}</summary><p>{h(a)}</p></details>' for q,a in questions)
    source_html=''.join(f'<a href="{u}" target="_blank" rel="noopener noreferrer">{h(n)}</a>' for n,u in [('Rockstar GTA VI',ROCKSTAR),('Rockstar preload FAQ','https://support.rockstargames.com/articles/7nPqOA2uCbpEQHXx7KVrYd/grand-theft-auto-vi-pre-load-faq'),('PlayStation GTA VI',PS5),('Rockstar game editions','https://support.rockstargames.com/articles/4QfG4FmZCf5W1gS8jy4UVT/grand-theft-auto-vi-platform-editions-and-versions')])
    body=page_intro('GTA 6: confirmed facts',desc,[('GTA 6 facts',path)])+f'''<main class="wrap info-page"><p class="lead">Last fact-check: <strong>November 18, 2026</strong>. This is a summary of publicly documented information, not access to a prerelease game build. After launch, gameplay claims must be verified separately.</p><h2>What is confirmed about GTA VI?</h2><div class="facts-grid">{fact_html}</div><h2>What is still unknown?</h2><p><strong>The complete building-by-building map:</strong> public community reconstructions help navigate Leonida, but Rockstar has not verified every road, building or enterable interior. <a href="/map/">Explore the labeled map</a>.</p><p><strong>PC specifications, cheat lists, vehicle speed rankings and a complete mission list:</strong> claims about these details require actual released-game evidence. We will not label untested rumors as confirmed.</p><h2>GTA 6 questions answered</h2><div class="faqs">{q_html}</div><h2>Original sources</h2><p>Read the source pages yourself. Rockstar defines the game's story and scope; platform guidance comes from the console makers. Do not substitute fan-made data for those disclosures.</p><div class="source-list">{source_html}</div><div class="note-box">GTASIX is an independent fan guide, not affiliated with or endorsed by Rockstar Games. For fast answers, start with our <a href="/guides/">guide library</a> or <a href="/characters/">character profiles</a>.</div></main>'''
    ld=[{'@context':'https://schema.org','@type':'FAQPage','@id':uri(path)+'#faq','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in questions]},
        {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':SITE_URL+'/'},{'@type':'ListItem','position':2,'name':'GTA 6 facts','item':uri(path)}]}]
    write(path,page('GTA 6 Confirmed Facts | GTASIX',desc,body,'',path,ld))

